public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i=0;i<n;i++) graph[i] = new ArrayList<>();
    for (int[] e: edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx=0;
    // DFS stack
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei: graph[node]) {
            if (nei == parent[node]) continue;
            parent[nei] = node;
            stack.push(nei);
        }
    }
    // Now process reverse order
    boolean[] hasSub = new boolean[n];
    int total=0;
    for (int i=n-1;i>=0;i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei: graph[node]) {
            if (nei == parent[node]) continue;
            if (hasSub[nei]) has = true;
        }
        hasSub[node] = has;
        if (node!=0 && has) {
            total += 2;
        }
    }
    return total;
}

